'use client';
import { useEffect, useState } from 'react';
import { usePathname } from 'next/navigation';
import { useSyncExternalStore } from 'react';
import { motion } from 'framer-motion';

const tabs = [
  { name: 'Overview', href: '/finance' },
  { name: 'Investments', href: '/finance/investments' },
  { name: 'Debt', href: '/finance/debt' },
  { name: 'Tracker', href: '/finance/tracker' },
  { name: 'Learning', href: '/finance/learning' },
];

const HeroScene = () => {
  const pathname = usePathname();
  const isActive = pathname === tabs[0].href;

  const [isWebGLAvailable, setIsWebGLAvailable] = useState(false);

  useEffect(() => {
    setIsWebGLAvailable(!!window.WebGLRenderingContext);
  }, []);

  const [isReducedMotion, setIsReducedMotion] = useState(false);

  useEffect(() => {
    setIsReducedMotion(window.matchMedia('(prefers-reduced-motion: reduce)').matches);
  }, []);

  const HeroThreeJS = dynamic(() => import('./HeroThreeJS'), { ssr: false });

  return (
    <div className="hero">
      <div className="hero-content">
        <div className="max-w-md">
          <h1 className="text-5xl font-bold">FINANCE OS</h1>
          <p className="py-6">Your personal finance assistant</p>
          <Link href="/finance/settings" className="btn btn-primary">Settings</Link>
        </div>
      </div>
      <div className="hero-image">
        {isWebGLAvailable && !isReducedMotion ? (
          <HeroThreeJS />
        ) : (
          <svg width="100%" height="100%" viewBox="0 0 100 100">
            <circle cx="50" cy="50" r="40" fill="blue" />
          </svg>
        )}
      </div>
    </div>
  );
};

export default HeroScene;
